import 'dart:async';

class Article {
  const Article({required this.id, required this.title, required this.source});
  final int id;
  final String title;
  final String source;
}

abstract interface class NewsRepository {
  Stream<List<Article>> watchLatest();
}

class FakeNewsRepository implements NewsRepository {
  static const _titles = ['کاهش ترافیک صبحگاهی', 'افتتاح کتابخانه‌ی محله', 'بارش برف در البرز'];

  @override
  Stream<List<Article>> watchLatest() async* {
    final items = <Article>[];
    for (var i = 0; i < _titles.length; i++) {
      await Future<void>.delayed(const Duration(seconds: 2));
      items.insert(0, Article(id: i, title: _titles[i], source: 'خبرگزاری فرضی'));
      yield List.unmodifiable(items); // a fresh, read-only snapshot
    }
  }
}

Future<void> main() async {
  await for (final list in FakeNewsRepository().watchLatest()) {
    print('${list.length} خبر؛ تازه‌ترین: ${list.first.title}');
  }
}

