class MockNewsRepository extends Mock implements NewsRepository {}
void main() {
  late MockNewsRepository repo;
  setUp(() => repo = MockNewsRepository());

  blocTest<NewsCubit, List<String>?>('emits every list from the repository',
      setUp: () => when(() => repo.watchLatest()).thenAnswer((_) => Stream.fromIterable([
            ['خبر اول'],
            ['خبر دوم', 'خبر اول'],
          ])),
      build: () => NewsCubit(repo),
      expect: () => [['خبر اول'], ['خبر دوم', 'خبر اول']]);

  blocTest<NewsCubit, List<String>?>('emits an empty list when offline',
      setUp: () => when(() => repo.watchLatest()).thenAnswer((_) => Stream.error(Exception('offline'))),
      build: () => NewsCubit(repo),
      expect: () => [isEmpty]);
}

