sealed class Failure implements Exception {
  const Failure(this.message);
  final String message;
}
class NetworkFailure extends Failure { const NetworkFailure() : super('اتصال اینترنت برقرار نیست'); }
class TimeoutFailure extends Failure { const TimeoutFailure() : super('سرور دیر پاسخ داد؛ دوباره تلاش کن'); }
class ServerFailure extends Failure {
  const ServerFailure(this.statusCode) : super('خطای سرور؛ کمی بعد دوباره امتحان کن');
  final int? statusCode;
}

Failure mapDioError(DioException e) => switch (e.type) {
      DioExceptionType.connectionTimeout ||
      DioExceptionType.sendTimeout ||
      DioExceptionType.receiveTimeout => const TimeoutFailure(),
      DioExceptionType.connectionError => const NetworkFailure(),
      DioExceptionType.badResponse => ServerFailure(e.response?.statusCode),
      _ => const ServerFailure(null),
    };

