  final T value;
  final DateTime savedAt;
  bool isFresh(Duration ttl) => DateTime.now().difference(savedAt) < ttl;
}

class RateCache {
  final _items = <String, CachedValue<int>>{};

  int? read(String code) {
    final hit = _items[code];
    return (hit != null && hit.isFresh(const Duration(minutes: 5))) ? hit.value : null;
  }

  void write(String code, int priceToman) => _items[code] = CachedValue(priceToman);
}

