import 'package:flutter/material.dart';

class ProductList extends StatefulWidget {
  const ProductList({super.key, required this.fetchPage});
  final Future<List<String>> Function(int page) fetchPage; // GET /products?page=..&limit=20
  @override
  State<ProductList> createState() => _ProductListState();
}

class _ProductListState extends State<ProductList> {
  static const _pageSize = 20;
  final _items = <String>[];
  var _page = 1, _loading = false, _hasMore = true;
  Future<void> _loadMore() async {
    if (_loading || !_hasMore) return;
    _loading = true;
    try {
      final next = await widget.fetchPage(_page);
      if (mounted) setState(() { _items.addAll(next); _page++; _hasMore = next.length == _pageSize; });
    } finally {
      _loading = false; // also after an error, so the next scroll can retry
    }
  }
  @override
  Widget build(BuildContext context) => ListView.builder(
        itemCount: _items.length + (_hasMore ? 1 : 0),
        itemBuilder: (_, i) {
          if (i >= _items.length - 5) _loadMore(); // near the end: fetch the next page
          return i < _items.length ? ListTile(title: Text(_items[i])) : const Center(child: CircularProgressIndicator());
        },
      );
}

