/// Item [index] of [count] fades and slides in, each one a little later.
Widget staggeredItem({
  required AnimationController controller,
  required int index,
  required int count,
  required Widget child,
}) {
  final interval = Interval(index / (count + 1), (index + 2) / (count + 1), curve: Curves.easeOut);
  final anim = controller.drive(CurveTween(curve: interval));
  return FadeTransition(
    opacity: anim,
    child: SlideTransition(
      position: anim.drive(Tween(begin: const Offset(0.2, 0), end: Offset.zero)),
      child: child,
    ),
  );
}

