class RingPainter extends CustomPainter {
  RingPainter(this.progress) : super(repaint: progress); // repaint on every tick
  final Animation<double> progress;
  @override
  void paint(Canvas canvas, Size size) {
    final rect = (Offset.zero & size).deflate(4);
    final track = Paint()..style = PaintingStyle.stroke..strokeWidth = 8..color = Colors.black12;
    final bar = Paint()
      ..style = PaintingStyle.stroke..strokeWidth = 8..strokeCap = StrokeCap.round..color = Colors.orange;
    canvas.drawArc(rect, 0, 2 * math.pi, false, track);
    canvas.drawArc(rect, -math.pi / 2, 2 * math.pi * progress.value, false, bar);
  }
  @override
  bool shouldRepaint(RingPainter oldDelegate) => oldDelegate.progress != progress;
}

