class RenderRateBar extends RenderBox {
  RenderRateBar(this._ratio);
  double _ratio;
  set ratio(double value) {
    if (value == _ratio) return;
    _ratio = value;
    markNeedsPaint(); // size does not change, so layout is skipped
  }

  @override
  void performLayout() => size = constraints.constrain(Size(constraints.maxWidth, 12));

  @override
  void paint(PaintingContext context, Offset offset) {
    final rect = offset & Size(size.width * _ratio, size.height);
    context.canvas.drawRect(rect, Paint()..color = const Color(0xFFFFA000));
  }
}

