import 'package:flutter/material.dart';
import 'package:get_it/get_it.dart';
import 'package:go_router/go_router.dart';

abstract interface class CartApi {
  Future<void> addProduct(int productId);
}
abstract interface class FeatureModule {
  void register(GetIt di);
  List<RouteBase> get routes;
}

class CartModule implements FeatureModule {
  @override
  void register(GetIt di) => di.registerLazySingleton<CartApi>(_FakeCart.new);
  @override
  List<RouteBase> get routes => [GoRoute(path: '/cart', builder: (_, _) => const Placeholder())];
}
class _FakeCart implements CartApi {
  @override
  Future<void> addProduct(int productId) async => debugPrint('cart: +$productId');
}

// App shell: the only place that knows every module
void main() {
  final modules = <FeatureModule>[CartModule()];
  for (final m in modules) {
    m.register(GetIt.I);
  }
  runApp(MaterialApp.router(routerConfig: GoRouter(
      initialLocation: '/cart', routes: [for (final m in modules) ...m.routes])));
}

