/// Converts Latin digits to Persian: '0912' -> '۰۹۱۲'.
String toPersianDigits(String input) {
  const persian = '۰۱۲۳۴۵۶۷۸۹';
  return input.replaceAllMapped(RegExp('[0-9]'), (m) => persian[int.parse(m[0]!)]);
}

/// Formats an amount with separators: 2450000 -> '۲٬۴۵۰٬۰۰۰ تومان'.
String formatToman(int amount) {
  final grouped = amount.toString().replaceAllMapped(
        RegExp(r'\B(?=(\d{3})+(?!\d))'),
        (_) => '٬',
      );
  return '${toPersianDigits(grouped)} تومان';
}

