import 'package:flutter_test/flutter_test.dart'; // in a pure Dart package: package:test

/// Validates an Iranian national code (10 digits, last one is a check digit).
bool isValidNationalCode(String code) {
  if (!RegExp(r'^\d{10}$').hasMatch(code)) return false;
  if (RegExp(r'^(\d)\1{9}$').hasMatch(code)) return false; // e.g. 1111111111
  final digits = code.split('').map(int.parse).toList();
  var sum = 0;
  for (var i = 0; i < 9; i++) {
    sum += digits[i] * (10 - i);
  }
  final r = sum % 11;
  return digits[9] == (r < 2 ? r : 11 - r);
}

void main() {
  group('isValidNationalCode', () {
    test('accepts a correct check digit', () {
      expect(isValidNationalCode('0012345679'), isTrue);
    });
    test('rejects a wrong check digit', () {
      expect(isValidNationalCode('0012345670'), isFalse);
    });
    test('rejects wrong length and repeated digits', () {
      expect(isValidNationalCode('12345'), isFalse);
      expect(isValidNationalCode('1111111111'), isFalse);
    });
  });
}
